  border-radius: var(--ep-radius-base);
  background: var(--ep-color-danger-soft);
}
.data-card-table {
  --el-table-border-color: var(--ep-color-border);
  --el-table-header-bg-color: var(--ep-color-surface-tinted);
  --el-table-header-text-color: var(--ep-color-text-secondary);
  --el-table-row-hover-bg-color: var(--ep-color-surface-hover);
